<?php
require __DIR__ . '/../config/config.php';
session_start(); if(empty($_SESSION['admin_id'])){header('Location: login.php');exit;}
$keys=['site_name','site_tagline','footer_description','phone','email','address','facebook_url','instagram_url','youtube_url','twitter_url','whatsapp_url'];
if($_SERVER['REQUEST_METHOD']==='POST'){ $q=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)'); foreach($keys as $key){$q->execute([$key,trim($_POST[$key]??'')]);} $saved='সেটিংস সংরক্ষণ হয়েছে।'; }
?><!doctype html><html lang="bn"><head><meta charset="utf-8"><title>Dashboard</title><link rel="stylesheet" href="../assets/style.css"><style>form{max-width:720px;margin:auto}label{display:block;margin-top:16px;color:#ffab00}input,textarea{width:100%;padding:14px;margin-top:6px;border-radius:10px;border:2px solid #34445e;background:#eef2f8;font-size:16px}textarea{min-height:100px}</style></head><body><main><section><h1>⚙ Admin Dashboard</h1><p><a class="button" href="../index.php">ওয়েবসাইট দেখুন</a> <a class="button" href="logout.php">Logout</a></p><?php if(!empty($saved)):?><p><?=e($saved)?></p><?php endif;?><form method="post"><h2>সাইট পরিচিতি</h2><?php foreach($keys as $key):?><label><?=e(ucwords(str_replace('_',' ',$key)))?><input name="<?=e($key)?>" value="<?=e(setting($key))?>"></label><?php endforeach;?><button class="button" type="submit">সেটিংস সংরক্ষণ করুন</button></form></section></main></body></html>
